-- Migration 133: three-level category tree (L1 > L2 > L3)
--
-- Generated by scripts/gen-category-tree-seed.mjs from docs/tree.csv. Do not hand-edit;
-- change the CSV or the mapping tables in that script and regenerate.
--
-- Additive and idempotent. categories_l3 keeps its primary key and every row, so the six
-- tables that reference it (projects, rfqs, compliance_requests, compliance_requirements,
-- product_features, supplier_proposals) and category_attributes are untouched.

BEGIN;

-- 1. Parent levels ---------------------------------------------------------

CREATE TABLE IF NOT EXISTS public.categories_l1 (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name       text NOT NULL UNIQUE,
  sort_order integer NOT NULL DEFAULT 0,
  active     boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.categories_l2 (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  l1_id      uuid NOT NULL REFERENCES public.categories_l1(id) ON DELETE RESTRICT,
  name       text NOT NULL,
  sort_order integer NOT NULL DEFAULT 0,
  active     boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (l1_id, name)
);

CREATE INDEX IF NOT EXISTS idx_categories_l2_l1_id ON public.categories_l2(l1_id);

-- 2. Hang the existing leaf table off L2 -----------------------------------
-- Nullable on purpose: a leaf with no parent is the "Uncategorised" bucket, which is
-- where unmatched legacy rows land rather than being deleted.

ALTER TABLE public.categories_l3
  ADD COLUMN IF NOT EXISTS l2_id uuid REFERENCES public.categories_l2(id) ON DELETE RESTRICT,
  ADD COLUMN IF NOT EXISTS sort_order integer NOT NULL DEFAULT 0;

CREATE INDEX IF NOT EXISTS idx_categories_l3_l2_id ON public.categories_l3(l2_id);

COMMENT ON COLUMN public.categories_l3.l2_id IS
  'Parent L2. NULL means uncategorised - the row is kept and usable but sits outside the tree.';

-- 3. RLS - mirror categories_l3 exactly ------------------------------------

ALTER TABLE public.categories_l1 ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.categories_l2 ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Enable all for categories_l1" ON public.categories_l1;
CREATE POLICY "Enable all for categories_l1" ON public.categories_l1
  FOR ALL USING (auth.role() = 'authenticated');

DROP POLICY IF EXISTS "Allow public read access to categories_l1" ON public.categories_l1;
CREATE POLICY "Allow public read access to categories_l1" ON public.categories_l1
  FOR SELECT USING (true);

DROP POLICY IF EXISTS "Enable all for categories_l2" ON public.categories_l2;
CREATE POLICY "Enable all for categories_l2" ON public.categories_l2
  FOR ALL USING (auth.role() = 'authenticated');

DROP POLICY IF EXISTS "Allow public read access to categories_l2" ON public.categories_l2;
CREATE POLICY "Allow public read access to categories_l2" ON public.categories_l2
  FOR SELECT USING (true);

