-- Rows with no place in the tree. Declared up front so the filing step below skips them:
-- the empty duplicate "Chimney Hoods" shares a name with a real leaf and would otherwise
-- be filed alongside it.
CREATE TEMP TABLE _retired_l3 (id uuid, note text) ON COMMIT DROP;
INSERT INTO _retired_l3 (id, note) VALUES
  ('c6d8d538-b51d-4309-9fae-4f6bea2e5584', 'Hobs - Test'),
  ('a93170ed-84f3-4224-a8e4-9c64af86cf70', 'Hoods - Test'),
  ('8d0d1798-782a-4501-bcbd-6fd1c0b3029a', 'Chimney Hoods (empty duplicate)');

-- 7a. File existing leaves under their L2 (id, attributes and FKs preserved).
--     Only ever fills a NULL parent, so a hand-placed row is never overwritten.
UPDATE public.categories_l3 c
SET l2_id = l2.id, sort_order = t.sort_order
FROM _tree_l3 t
JOIN public.categories_l1 l1 ON l1.name = t.l1_name
JOIN public.categories_l2 l2 ON l2.l1_id = l1.id AND l2.name = t.l2_name
WHERE c.name = t.l3_name
  AND c.l2_id IS NULL
  AND c.id NOT IN (SELECT id FROM _retired_l3);

-- 7b. Insert the leaves that do not exist yet. A retired row does not count as an
--     existing leaf, so the real "Chimney Hoods" is still seeded if only the dup remains.
INSERT INTO public.categories_l3 (name, l2_id, sort_order, active, is_finalized)
SELECT t.l3_name, l2.id, t.sort_order, true, false
FROM _tree_l3 t
JOIN public.categories_l1 l1 ON l1.name = t.l1_name
JOIN public.categories_l2 l2 ON l2.l1_id = l1.id AND l2.name = t.l2_name
WHERE NOT EXISTS (
  SELECT 1 FROM public.categories_l3 c
  WHERE c.name = t.l3_name AND c.id NOT IN (SELECT id FROM _retired_l3)
);

-- 8. Retire the rows with no place in the tree ------------------------------
-- Kept, not deleted: deactivated and unparented so they show as Uncategorised and stay
-- out of the pickers. Reversible with a single UPDATE.

UPDATE public.categories_l3 c
SET active = false, l2_id = NULL
FROM _retired_l3 r
WHERE c.id = r.id;

NOTIFY pgrst, 'reload schema';

COMMIT;
